#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long a;
    long long b;
    cin >> a >> b;

    if (a > b) {
        cout << a << endl;
    } else {
        cout << b << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        long b = sc.nextLong();

        if (a > b) {
            System.out.println(a);
        } else {
            System.out.println(b);
        }
    }
}
